@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Oswald:wght@400;500;600;700&display=swap');
:root{--ink:#f4f0e5;--muted:#a9b3a5;--gold:#e5b96e;--deep:#13211d;--panel:rgba(17,29,25,.89);--line:rgba(238,231,207,.15);--sans:'DM Sans',Arial,sans-serif;--display:'Oswald','Arial Narrow',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#15241e;color:var(--ink);font-family:var(--sans);user-select:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#5c907f}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,19,17,.47),transparent 22%,transparent 65%,rgba(9,19,17,.46)),radial-gradient(ellipse at 50% 45%,transparent 43%,rgba(9,18,16,.21) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(12,24,20,.48),transparent)}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#f6f1e4;font:600 16px var(--display);letter-spacing:1.9px}.brand-mark{width:29px;height:29px;border:1px solid #d5b57b;color:#e5be79;display:grid;place-items:center;font:600 16px var(--display);transform:rotate(45deg)}.brand-mark::first-letter{transform:rotate(-45deg)}.brand-light{font-weight:400;color:#c2cbbd;margin-left:4px}.location{display:flex;align-items:center;gap:10px;font-size:10px;letter-spacing:1.8px;font-weight:600;color:#eef0df}.location i{font-style:normal;color:#e5b96e;font-size:16px}.pulse{width:7px;height:7px;border-radius:50%;background:#c9d88b;box-shadow:0 0 10px #d0e08b}.top-actions{display:flex;align-items:center;gap:10px}.icon-btn,.pause-btn{background:rgba(12,26,22,.45);border:1px solid rgba(255,255,255,.2);height:36px;min-width:37px;cursor:pointer;transition:.2s}.icon-btn:hover,.pause-btn:hover{background:rgba(229,185,110,.2);border-color:#e5b