@media(max-width:600px){.topbar{height:48px;padding:0 10px}.brand{font-size:11px;gap:7px;letter-spacing:1px}.brand-mark{width:23px;height:23px}.location{gap:5px;font-size:7px}.top-actions{gap:5px}.icon-btn,.pause-btn{height:29px;min-width:30px;padding:0 7px}.pause-btn span{display:none}.hud-left{top:59px;left:9px;width:153px}.player-chip{gap:7px}.avatar{width:28px;height:28px;font-size:9px}.player-chip strong{font-size:10px}.player-chip small{font-size:7px}.survival-card{padding:8px;margin-top:4px}.status-row{gap:6px;margin-bottom:8px}.status-info b{font-size:7px}.status-info span{font-size:8px}.status-icon{font-size:11px;width:13px}.weather-chip{margin-top:4px;padding:6px;font-size:14px}.weather-chip div b{font-size:8px}.weather-chip small{font-size:6px}.quest-card{top:auto;bottom:100px;right:9px;width:178px;padding:10px}.quest-card h2{font-size:14px;margin:6px 0 3px}.quest-card p{font-size:8px;margin-bottom:8px}.quest-top .eyebrow,.quest-count{font-size:7px}.quest-objective{font-size:8px;padding-top:8px}.journal-link{padding-top:8px;font-size:8px}.bottom-left{left:9px;bottom:12px;gap:4px}.round-button{width:31px;height:31px;font-size:14px}.bottom-label{display:none}.hotbar{bottom:56px;left:9px;transform:none;gap:3px}.hotbar-slot{width:42px;height:44px}.slot-icon{font-size:14px}.hotbar-slot small{font-size:6px}.hotbar-hint{display:none}.compass{display:none}.menu-screen{padding:0 8%;align-items:center;background:linear-gradient(90deg,rgba(11,23,20,.84),rgba(13,25,20,.4) 80%)}.menu-copy{margin-top:35px}.menu-copy h1{font-size:64px;margin:18px 0 7px}.subtitle{font-size:11px;letter-spacing:5px;margin:12px 0}.menu-description{font-size:11px;margin-bottom:17px}.game-kicker{font-size:8px}.primary-button{width:220px;height:42px}.menu-footer{bottom:14px;font-size:6px}.menu-side{display:none}.mobile-controls{display:block}.joystick{position:absolute;z-index:3;left:18px;bottom:70px;width:94px;height:94px;border:1px solid rgba(240,238,216,.38);background:rgba(18,30,25,.22);border-radius:50%;touch-action:none}.joy-knob{position:absolute;width:38px;height:38px;border-radius:50%;left:27px;top:27px;background:rgba(235,220,178,.4);border:1px solid rgba(255,255,255,.45)}.mobile-actions{position:absolute;right:14px;bottom:64px;z-index:3;display:grid;grid-template-columns:repeat(2,47px);gap:7px}.mobile-actions button{height:47px;border-radius:50%;background:rgba(18,30,25,.65);border:1px solid rgba(240,238,216,.4);font-size:17px}.mobile-actions small{display:block;font:500 6px var(--display);letter-spacing:.8px}.bottom-left{bottom:12px}.hotbar{bottom:12px;left:50%;transform:translateX(-50%)}.hotbar-slot{width:39px;height:40px}.hotbar-slot:nth-child(n+4){display:none}.quest-card{bottom:160px}.panel{padding:28px 20px}.item-grid{grid-template-columns:repeat(2,1fr)}.item-card{min-height:70px;padding:8px}.panel h2{font-size:23px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#world'), ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const rand = (a,b) => a + Math.random()*(b-a);
  let W=innerWidth,H=innerHeight,DPR=1, started=false, paused=false, panelMode='', last=0, gameTime=8.25, toastTimer=0, lastSave=0;
  const player={x:490,y:470,dir:0,speed:160,health:100,hunger:82,thirst:68,stamina:100,wood:0,stone:0,fiber:0,berries:2,coconut:0,meat:0,water:1,axe:true,level:1};
  const inventory={Driftwood:0,Stone:0,PlantFiber:0,Coconut:0,WildBerries:2,CleanWater:1,RawMeat:0,StoneAxe:1,WoodenSpear:0,Bandage:1};
  const keys={}, world={width:1900,height:1400, camera:{x:0,y:0}, objects:[], animals:[], particles:[]};
  const quests=[
    ['A FRESH START','The tide left a few useful things behind. Gather what you can.','Collect driftwood',3,'Driftwood'],
    ['FIND YOUR BEARINGS','You have enough to make a start. Find stones for a simple tool.','Gather smooth stones',3,'Stone'],
    ['A TOOL FOR THE WILD','A sharp edge changes everything. Craft a stone axe.','Craft a stone axe',1,'StoneAxe'],
    ['SHELTER FROM THE STORM','The jungle is beautiful, but night comes quickly.','Craft a basic shelter',1,'Shelter'],
    ['FIRST FLAME','A small fire means warmth, light, and a hot meal.','Build a campfire',1,'Campfire'],
    ['INTO THE GREEN','Follow the trail inland. Something has been here before.','Explore the forest',1,'Explore']
  ]; let questIndex=0,questProgress=0, shelterPlaced=false, campfirePlaced=false;
  const recipes=[
    {name:'Wooden Spear',icon:'⟋',cost:{Driftwood:3,PlantFiber:2},desc:'A reliable tool for keeping danger at a distance.'},
    {name:'Stone Axe',icon:'🪓',cost:{Driftwood:2,Stone:3,PlantFiber:1},desc:'Harvest branches and gather wood more efficiently.'},
    {name:'Stone Knife',icon:'†',cost:{Stone:2,PlantFiber:1},desc:'A sharp edge for gathering and preparing food.'},
    {name:'Campfire',icon:'♨',cost:{Driftwood:5,Stone:3},desc:'Warmth, light, and a place to cook your catch.'},
    {name:'Basic Shelter',icon:'⌂',cost:{Driftwood:8,PlantFiber:5},desc:'A simple palm shelter. Rest safely through the night.'},
    {name:'Bandage',icon:'＋',cost:{PlantFiber:4},desc:'Stop bleeding and restore a little health.'}
  ];
  const input={x:0,y:0,sprint:false};
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}
  addEventListener('resize',resize);resize();
  function makeWorld(){
    let seed=8731;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
    const add=(type,x,y,extra={})=>world.objects.push({type,x,y,active:true,...extra});
    for(let i=0;i<60;i++){let x=160+random()*1530,y=70+random()*1250;if(y>470&&y<590&&x>260&&x<760)continue;let type=random()<.58?'tree':random()<.65?'bush':'fern';add(type,x,y,{scale:.7+random()*.8,variant:Math.floor(random()*4)})}
    for(let i=0;i<14;i++)add('driftwood',210+random()*900,500+random()*310,{scale:.7+random()*.6});
    for(let i=0;i<23;i++)add('stone',300+random()*1250,350+random()*850,{scale:.65+random()*.55});
    for(let i=0;i<13;i++)add('berry',650+random()*850,320+random()*850,{scale:.8+random()*.4});
    for(let i=0;i<7;i++)add('coconut',260+random()*600,200+random()*450,{scale:.8});
    add('wreck',320,410,{scale:1.15});
    for(let i=0;i<4;i++)world.animals.push({x:900+random()*500,y:380+random()*480,phase:random()*7,alive:true});
  }
  makeWorld();
  function project(x,y){return {x:x-world.camera.x+W/2,y:y-world.camera.y+H/2}}
  function ellipse(x,y,rx,ry,color,alpha=1){ctx.globalAlpha=alpha;ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
  function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
  function drawGround(){
    const ox=W/2-world.camera.x,oy=H/2-world.camera.y;
